```java
import java.time.Duration;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Configuration;
import org.springframework.stereotype.Component;
import org.springframework.validation.annotation.Validated;

@ConfigurationProperties("payment")
@Validated
record PaymentProperties(
        @NotBlank String baseUrl,
        @NotNull Duration timeout,
        @Min(0) int maxRetries) {}

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(PaymentProperties.class)
class PaymentConfiguration {}

@Component
class Banner {
    private final String text;

    Banner(@Value("${app.banner:Orders}") String text) {
        this.text = text;
    }
}
```

`PaymentProperties` keeps three related values together and validates them. `Banner` demonstrates the smaller `@Value` use case.

```java
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class HttpSmokeTest {
    @LocalServerPort
    int port;

    @Test
    void serverHasAnAssignedPort() {
        assertTrue(port > 0);
    }
}
```

`RANDOM_PORT` starts the server with port zero and `@LocalServerPort` injects the actual port selected after startup.
